import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, time, Fn, vec2, vec3, fract, sin, dot, add, mul, sub } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, SRGBColorSpace } = ctx.THREE;

  const group = new Group();
  group.name = 'hub-features-card-1';

  // Atlas source rect 512x320 -> aspect 1.6:1
  const planeW = 2.0;
  const planeH = planeW / 1.6;

  const geometry = new PlaneGeometry(planeW, planeH, 1, 1);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: ctx.THREE.DoubleSide,
  });

  const plane = new Mesh(geometry, material);
  plane.renderOrder = 1;
  group.add(plane);

  // Subtle film grain via TSL hash noise (static composition, no interactivity)
  const grain = Fn(() => {
    const p = uv().mul(vec2(900.0, 562.5)).add(time.mul(7.0));
    const h = fract(sin(dot(p, vec2(12.9898, 78.233))).mul(43758.5453));
    return h.sub(0.5);
  });

  const imageUrl = config.imageUrl;
  let loadedTexture = null;

  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    loadedTexture = tex;
    tex.colorSpace = SRGBColorSpace;
    tex.anisotropy = 8;
    tex.minFilter = ctx.THREE.LinearMipmapLinearFilter;
    tex.magFilter = ctx.THREE.LinearFilter;
    tex.generateMipmaps = true;
    tex.needsUpdate = true;

    const baseColor = texture(tex, uv());
    // Apply very subtle grain (<=0.03 luma) over the engineered-gradient surface
    const g = grain().mul(0.03);
    material.colorNode = add(baseColor, vec3(g, g, g));
    material.needsUpdate = true;
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  return group;
}
